CREATE TABLE session.observation_fragment_history(task_id text NOT NULL,seq bigint NOT NULL,document jsonb NOT NULL,PRIMARY KEY(task_id,seq));
CREATE FUNCTION session.original_observation_fragment(body jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$ SELECT jsonb_build_object('agentId',body->>'agentId','type',CASE WHEN body->>'type'='text' THEN 'status' ELSE body->>'type' END,'at',body->>'at','sessionId',body->>'sessionId','toolId',body->'tool'->>'callId','toolName',body->'tool'->>'name','error',body->'tool'->'isError','status',CASE WHEN body->>'type'='text' THEN 'active' ELSE body->>'status' END) $$;
CREATE FUNCTION session.retain_observation_fragment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.kind='agent' AND NEW.event->'event'->>'type' IN('started','session','tool-start','tool-end','permission','status','error','completed','cancelled','text') THEN INSERT INTO session.observation_fragment_history VALUES(NEW.task_id,NEW.seq,session.original_observation_fragment(NEW.event->'event')) ON CONFLICT DO NOTHING;END IF;RETURN NULL;END $$;
CREATE TRIGGER retain_observation_fragment AFTER INSERT ON session.runner_events FOR EACH ROW EXECUTE FUNCTION session.retain_observation_fragment();
INSERT INTO session.observation_fragment_history SELECT task_id,seq,session.original_observation_fragment(event->'event') FROM session.runner_events WHERE kind='agent' AND event->'event'->>'type' IN('started','session','tool-start','tool-end','permission','status','error','completed','cancelled','text') ON CONFLICT DO NOTHING;
CREATE TRIGGER session_observation_content BEFORE INSERT OR UPDATE OR DELETE ON session.observation_fragment_history FOR EACH ROW EXECUTE FUNCTION session.guard_content();
CREATE TRIGGER session_observation_truncate BEFORE TRUNCATE ON session.observation_fragment_history EXECUTE FUNCTION session.reject_truncate();
